// ============================================================
// SHYNETYME BT V5.2 MAIN
// Classic ESP32 + WS2812B/WS281x + BLE
// - true 3-color engine: BG / FG / MAIN with independent role brightness
// - runtime RGB byte-order mapping: RGB/GRB/BRG/GBR/RBG/BGR
// - audio is a low-latency modulation stream, not a separate effect selector
// - compact A=xxxxxxxxb audio packet avoids BLE write/notify congestion
// - NVS startup state + 8 persistent preset slots; no battery-backed memory required
// - effects never own or reset brightness/colors; Live Control owns parameters
// - new show effects: Sonic Stream/Boom, Ripple, Starburst, Balls, Popcorn,
//   DripDrop, Lava Lamp, Magma, Aurora, Juggle, Sinelon, Heartbeat
// - live LED-count changes; GPIO changes take effect after reboot
// - same BLE UUID family as earlier ShyneTyme controllers
// - V5.2 WLED-compatible 1D catalog layer (panel/2D-only effects excluded)
// - all newly added catalog effects are constrained to BG / FG / MAIN roles only
// - optional 16-bin FFT packet (F=<32 hex chars>[beat]) while preserving V5.1 A= packet
// - every effect remains audio-follow capable through common level/beat/spectrum modulation
// ============================================================

#define MAX_LEDS 600
#define DEFAULT_LED_COUNT 300
#define DEFAULT_DATA_PIN 13
#define LED_TYPE WS2812B

#define SERVICE_UUID "78170001-7A32-4B19-913A-5354594D4501"
#define COMMAND_UUID "78170002-7A32-4B19-913A-5354594D4501"
#define STATUS_UUID  "78170003-7A32-4B19-913A-5354594D4501"

