// ---------- SMALL HELPERS ----------
uint8_t clamp8i(int v){ if(v<0)return 0; if(v>255)return 255; return (uint8_t)v; }
uint8_t mix8(uint8_t a,uint8_t b,uint8_t amt){ return (uint8_t)(a+(((int)b-(int)a)*(int)amt)/255); }
CRGB mixColor(const CRGB& a,const CRGB& b,uint8_t amt){ return CRGB(mix8(a.r,b.r,amt),mix8(a.g,b.g,amt),mix8(a.b,b.b,amt)); }
CRGB scaled(const CRGB& c,uint8_t amount){ CRGB x=c; x.nscale8_video(amount); return x; }
void refreshRoleColors(){
  backgroundColor=scaled(backgroundBase,backgroundBrightness);
  foregroundColor=scaled(foregroundBase,foregroundBrightness);
  mainColor=scaled(mainBase,mainBrightness);
}
uint32_t packColor(const CRGB& c){ return ((uint32_t)c.r<<16)|((uint32_t)c.g<<8)|c.b; }
CRGB unpackColor(uint32_t v){ return CRGB((v>>16)&0xFF,(v>>8)&0xFF,v&0xFF); }
CRGB hexToColor(String s){ s.replace("#",""); if(s.length()!=6)return CRGB::Black; return unpackColor(strtoul(s.c_str(),nullptr,16)); }
String colorToHex(const CRGB& c){ char b[7]; snprintf(b,sizeof(b),"%02X%02X%02X",c.r,c.g,c.b); return String(b); }

String orderName(){
  switch(pixelOrder){case PO_RGB:return "RGB";case PO_GRB:return "GRB";case PO_BRG:return "BRG";case PO_GBR:return "GBR";case PO_RBG:return "RBG";case PO_BGR:return "BGR";} return "GRB";
}
bool setOrder(String s){
  s.toUpperCase();
  if(s=="RGB")pixelOrder=PO_RGB; else if(s=="GRB")pixelOrder=PO_GRB; else if(s=="BRG")pixelOrder=PO_BRG;
  else if(s=="GBR")pixelOrder=PO_GBR; else if(s=="RBG")pixelOrder=PO_RBG; else if(s=="BGR")pixelOrder=PO_BGR; else return false;
  return true;
}
CRGB mapPhysical(const CRGB& c){
  switch(pixelOrder){
    case PO_RGB:return CRGB(c.r,c.g,c.b); case PO_GRB:return CRGB(c.g,c.r,c.b); case PO_BRG:return CRGB(c.b,c.r,c.g);
    case PO_GBR:return CRGB(c.g,c.b,c.r); case PO_RBG:return CRGB(c.r,c.b,c.g); case PO_BGR:return CRGB(c.b,c.g,c.r);
  }
  return c;
}

String audioModeName(){
  switch(audioMode){case AM_OFF:return "OFF";case AM_LEVEL:return "LEVEL";case AM_BEAT:return "BEAT";case AM_SPECTRUM:return "SPECTRUM";case AM_FULL:return "FULL";} return "FULL";
}
bool setAudioMode(String s){
  s.toUpperCase();
  if(s=="OFF")audioMode=AM_OFF; else if(s=="LEVEL")audioMode=AM_LEVEL; else if(s=="BEAT")audioMode=AM_BEAT;
  else if(s=="SPECTRUM")audioMode=AM_SPECTRUM; else if(s=="FULL")audioMode=AM_FULL; else return false;
  return true;
}
bool audioLive(){ return audioEnabled&&audioMode!=AM_OFF&&(millis()-lastAudioPacket<1400); }
bool beatLive(){ return audioLive()&&(millis()-lastBeatAt<150); }
uint8_t reactiveSpeed(){
  if(!audioLive()||(audioMode!=AM_LEVEL&&audioMode!=AM_FULL))return effectSpeed;
  int boost=((int)audioBass*(int)audioAmount)/510;
  return clamp8i(effectSpeed+boost);
}
uint8_t reactiveIntensity(){
  if(!audioLive()||(audioMode!=AM_LEVEL&&audioMode!=AM_FULL))return effectIntensity;
  int boost=((int)audioLevel*(int)audioAmount)/560;
  return clamp8i(effectIntensity+boost);
}
uint8_t reactiveSize(){
  if(!audioLive()||(audioMode!=AM_LEVEL&&audioMode!=AM_FULL))return effectSize;
  int boost=((int)audioMid*(int)audioAmount)/620;
  return clamp8i(effectSize+boost);
}
uint8_t reactiveDensity(){
  if(!audioLive()||(audioMode!=AM_LEVEL&&audioMode!=AM_FULL))return effectDensity;
  int boost=((int)audioHigh*(int)audioAmount)/620;
  return clamp8i(effectDensity+boost);
}

uint16_t dirIndex(uint16_t i){ return directionForward?i:(activeLedCount-1-i); }
void putPixel(uint16_t i,const CRGB& c){
  if(i>=activeLedCount)return;
  uint16_t p=dirIndex(i); leds[p]=c;
  if(mirrorMode){uint16_t m=activeLedCount-1-p;if(m<activeLedCount)leds[m]=c;}
}
void addPixel(uint16_t i,const CRGB& c){
  if(i>=activeLedCount)return;
  uint16_t p=dirIndex(i); leds[p]+=c;
  if(mirrorMode){uint16_t m=activeLedCount-1-p;if(m<activeLedCount)leds[m]+=c;}
}
void fadeTowardBackground(uint8_t amount){ for(uint16_t i=0;i<activeLedCount;i++)leds[i]=mixColor(leds[i],backgroundColor,amount); }
void clearUnused(){ for(uint16_t i=activeLedCount;i<MAX_LEDS;i++){leds[i]=CRGB::Black;outputLeds[i]=CRGB::Black;} }
void showFrame(){
  for(uint16_t i=0;i<activeLedCount;i++)outputLeds[i]=mapPhysical(leds[i]);
  for(uint16_t i=activeLedCount;i<MAX_LEDS;i++)outputLeds[i]=CRGB::Black;
  FastLED.show();
}

