String catalogEffectName(){
  if(catalogEffect>=WLED_CATALOG_COUNT)return "WLED_UNKNOWN";
  return String(WLED_CATALOG[catalogEffect].name);
}
int16_t findCatalogEffect(String s){
  for(uint8_t i=0;i<WLED_CATALOG_COUNT;i++)if(s==WLED_CATALOG[i].name)return i;
  // Current WLED/docs aliases and retired-name compatibility.
  if(s=="PS_SPRING")return findCatalogEffect("PS_SPRINGY");
  if(s=="CANDY_CANE")return findCatalogEffect("CHASE_2");
  if(s=="HALLOWEEN")return findCatalogEffect("CHASE_2");
  if(s=="MERRY_CHRISTMAS")return findCatalogEffect("CHASE_2");
  if(s=="POLICE_ALL"||s=="TWO_AREAS")return findCatalogEffect("TWO_DOTS");
  return -1;
}
CRGB catalogRole(uint8_t role){
  switch(role%3){case 0:return backgroundColor;case 1:return foregroundColor;default:return mainColor;}
}
CRGB catalogRoleScaled(uint8_t role,uint8_t level){return scaled(catalogRole(role),level);}
uint8_t audioBin(uint8_t i){
  i&=15;
  if(millis()-lastSpectrumPacket<1400)return audioBins[i];
  // V5.1 4-value audio packets still drive the 16-bin engine.
  if(i<4)return audioBass;
  if(i<10)return audioMid;
  return audioHigh;
}
void clearCatalogParticles(){for(auto &p:particles)p.active=false;}
void resetCatalogState(){
  clearCatalogParticles();
  memset(heatMap,0,sizeof(heatMap));
  motionPos=0;chaseOffset=0;wavePhase=0;scannerPosition=0;scannerDirection=1;
}

// ---------- SETTINGS ----------
void loadSettings(){
  prefs.begin("shynetyme",true);
  ledCount=prefs.getUShort("ledcount",DEFAULT_LED_COUNT);dataPin=prefs.getUChar("pin",DEFAULT_DATA_PIN);
  brightness=prefs.getUChar("bright",96);effectSpeed=prefs.getUChar("speed",180);effectIntensity=prefs.getUChar("intensity",180);
  effectSize=prefs.getUChar("size",96);effectDensity=prefs.getUChar("density",128);effectTrail=prefs.getUChar("trail",170);
  directionForward=prefs.getBool("dir",true);mirrorMode=prefs.getBool("mirror",false);
  backgroundBase=unpackColor(prefs.getUInt("bg",0x000000));foregroundBase=unpackColor(prefs.getUInt("fg",0x8000FF));mainBase=unpackColor(prefs.getUInt("main",0xFFFFFF));
  backgroundBrightness=prefs.getUChar("bgbri",prefs.getUChar("bgb",64));foregroundBrightness=prefs.getUChar("fgbri",prefs.getUChar("fgb",220));mainBrightness=prefs.getUChar("mainbri",prefs.getUChar("mainb",180));
  pixelOrder=(PixelOrder)constrain((int)prefs.getUChar("order",PO_GRB),0,5);
  audioMode=(AudioMode)constrain((int)prefs.getUChar("audmode",AM_FULL),0,4);audioAmount=prefs.getUChar("audamt",210);
  String fx=prefs.getString("fxname","LIGHTNING");
  prefs.end();
  if(ledCount<1)ledCount=1;if(ledCount>MAX_LEDS)ledCount=MAX_LEDS;activeLedCount=ledCount;activeDataPin=dataPin;
  refreshRoleColors();setEffect(fx);
}
void saveSettings(){
  prefs.begin("shynetyme",false);
  prefs.putUShort("ledcount",ledCount);prefs.putUChar("pin",dataPin);prefs.putUChar("bright",brightness);prefs.putUChar("speed",effectSpeed);prefs.putUChar("intensity",effectIntensity);
  prefs.putUChar("size",effectSize);prefs.putUChar("density",effectDensity);prefs.putUChar("trail",effectTrail);prefs.putBool("dir",directionForward);prefs.putBool("mirror",mirrorMode);
  prefs.putUInt("bg",packColor(backgroundBase));prefs.putUInt("fg",packColor(foregroundBase));prefs.putUInt("main",packColor(mainBase));
  prefs.putUChar("bgbri",backgroundBrightness);prefs.putUChar("fgbri",foregroundBrightness);prefs.putUChar("mainbri",mainBrightness);
  prefs.putUChar("order",(uint8_t)pixelOrder);prefs.putUChar("audmode",(uint8_t)audioMode);prefs.putUChar("audamt",audioAmount);prefs.putString("fxname",effectName());prefs.end();
}
void savePreset(uint8_t slot){
  if(slot<1||slot>8)return;char ns[8];snprintf(ns,sizeof(ns),"stp%u",slot);prefs.begin(ns,false);
  prefs.putUChar("bright",brightness);prefs.putUChar("speed",effectSpeed);prefs.putUChar("intensity",effectIntensity);prefs.putUChar("size",effectSize);prefs.putUChar("density",effectDensity);prefs.putUChar("trail",effectTrail);
  prefs.putBool("dir",directionForward);prefs.putBool("mirror",mirrorMode);prefs.putUInt("bg",packColor(backgroundBase));prefs.putUInt("fg",packColor(foregroundBase));prefs.putUInt("main",packColor(mainBase));
  prefs.putUChar("bgbri",backgroundBrightness);prefs.putUChar("fgbri",foregroundBrightness);prefs.putUChar("mainbri",mainBrightness);prefs.putUChar("audmode",(uint8_t)audioMode);prefs.putUChar("audamt",audioAmount);prefs.putString("fx",effectName());prefs.putBool("used",true);prefs.end();
}
bool loadPreset(uint8_t slot){
  if(slot<1||slot>8)return false;char ns[8];snprintf(ns,sizeof(ns),"stp%u",slot);prefs.begin(ns,true);bool used=prefs.getBool("used",false);if(!used){prefs.end();return false;}
  brightness=prefs.getUChar("bright",brightness);effectSpeed=prefs.getUChar("speed",effectSpeed);effectIntensity=prefs.getUChar("intensity",effectIntensity);effectSize=prefs.getUChar("size",effectSize);effectDensity=prefs.getUChar("density",effectDensity);effectTrail=prefs.getUChar("trail",effectTrail);
  directionForward=prefs.getBool("dir",directionForward);mirrorMode=prefs.getBool("mirror",mirrorMode);backgroundBase=unpackColor(prefs.getUInt("bg",packColor(backgroundBase)));foregroundBase=unpackColor(prefs.getUInt("fg",packColor(foregroundBase)));mainBase=unpackColor(prefs.getUInt("main",packColor(mainBase)));
