// ---------- LED GPIO ----------
// FastLED is fixed to RGB serialization; mapPhysical() performs the selectable byte order.
// This avoids compiling 6 color-order variants for every supported GPIO.
#define ADD_LED_PIN(P) FastLED.addLeds<LED_TYPE,P,RGB>(outputLeds,MAX_LEDS)
bool configureLEDOutput(uint8_t pin){
  activeDataPin=pin;
  switch(pin){
    case 2:ADD_LED_PIN(2);break;case 4:ADD_LED_PIN(4);break;case 5:ADD_LED_PIN(5);break;case 12:ADD_LED_PIN(12);break;case 13:ADD_LED_PIN(13);break;
    case 14:ADD_LED_PIN(14);break;case 15:ADD_LED_PIN(15);break;case 16:ADD_LED_PIN(16);break;case 17:ADD_LED_PIN(17);break;case 18:ADD_LED_PIN(18);break;
    case 19:ADD_LED_PIN(19);break;case 21:ADD_LED_PIN(21);break;case 22:ADD_LED_PIN(22);break;case 23:ADD_LED_PIN(23);break;case 25:ADD_LED_PIN(25);break;
    case 26:ADD_LED_PIN(26);break;case 27:ADD_LED_PIN(27);break;case 32:ADD_LED_PIN(32);break;case 33:ADD_LED_PIN(33);break;
    default:dataPin=DEFAULT_DATA_PIN;activeDataPin=DEFAULT_DATA_PIN;ADD_LED_PIN(DEFAULT_DATA_PIN);return false;
  }
  return true;
}

