  else if(s=="BOUNCING_BALLS"||s=="BALLS")currentEffect=FX_BOUNCING_BALLS;else if(s=="POPCORN")currentEffect=FX_POPCORN;else if(s=="DRIPDROP"||s=="DRIP")currentEffect=FX_DRIPDROP;
  else if(s=="LAVA_LAMP"||s=="LAVA")currentEffect=FX_LAVA_LAMP;else if(s=="MAGMA")currentEffect=FX_MAGMA;else if(s=="AURORA")currentEffect=FX_AURORA;else if(s=="HEARTBEAT")currentEffect=FX_HEARTBEAT;
  else if(s=="BREATHE")currentEffect=FX_BREATHE;
  else if(s=="FLASH")currentEffect=FX_FLASH;else if(s=="DUAL_FLASH")currentEffect=FX_DUAL_FLASH;else if(s=="VU")currentEffect=FX_VU;
