  s+=";AUDIO="+String(audioEnabled?1:0);s+=";AUDLIVE="+String(audioLive()?1:0);s+=";AUDMODE="+audioModeName();s+=";AUDAMT="+String(audioAmount);s+=";LEVEL="+String(audioLevel);s+=";BASS="+String(audioBass);s+=";MID="+String(audioMid);s+=";HIGH="+String(audioHigh);
