// ---------- COMMANDS ----------
void touchAudio(){lastAudioPacket=millis();}
uint8_t hexByteAt(const String& s,uint8_t p){char b[3]={0,0,0};if(p+1>=s.length())return 0;b[0]=s[p];b[1]=s[p+1];return (uint8_t)strtoul(b,nullptr,16);}
void synthesizeBinsFromFour(){
  for(uint8_t i=0;i<4;i++)audioBins[i]=audioBass;
  for(uint8_t i=4;i<10;i++)audioBins[i]=audioMid;
  for(uint8_t i=10;i<16;i++)audioBins[i]=audioHigh;
}
void summarizeBins(){
  uint16_t bass=0,mid=0,high=0;uint8_t peak=0;
  for(uint8_t i=0;i<16;i++){uint8_t v=audioBins[i];if(v>peak)peak=v;if(i<4)bass+=v;else if(i<10)mid+=v;else high+=v;}
  audioBass=(uint8_t)(bass/4);audioMid=(uint8_t)(mid/6);audioHigh=(uint8_t)(high/6);
  audioLevel=(uint8_t)(((uint16_t)peak+(uint16_t)audioBass+(uint16_t)audioMid+(uint16_t)audioHigh)>>2);
}
void processSingleCommand(String command){
  command.trim();if(!command.length())return;int split=command.indexOf('=');String key=(split>=0)?command.substring(0,split):command;String value=(split>=0)?command.substring(split+1):"";
  key.trim();value.trim();key.toUpperCase();
  if(key=="FX")setEffect(value);
  else if(key=="BG"){backgroundBase=hexToColor(value);refreshRoleColors();}
  else if(key=="FG"){foregroundBase=hexToColor(value);refreshRoleColors();}
  else if(key=="MAIN"||key=="ACC"){mainBase=hexToColor(value);refreshRoleColors();}
  else if(key=="BGB"||key=="BGBRI"){backgroundBrightness=(uint8_t)constrain(value.toInt(),0,255);refreshRoleColors();}
  else if(key=="FGB"||key=="FGBRI"){foregroundBrightness=(uint8_t)constrain(value.toInt(),0,255);refreshRoleColors();}
  else if(key=="MAINB"||key=="MAINBRI"){mainBrightness=(uint8_t)constrain(value.toInt(),0,255);refreshRoleColors();}
  else if(key=="BRI"){brightness=(uint8_t)constrain(value.toInt(),0,255);FastLED.setBrightness(brightness);}else if(key=="SPD")effectSpeed=(uint8_t)constrain(value.toInt(),1,255);else if(key=="INT")effectIntensity=(uint8_t)constrain(value.toInt(),1,255);
  else if(key=="SIZE")effectSize=(uint8_t)constrain(value.toInt(),1,255);else if(key=="DENS"||key=="DENSITY")effectDensity=(uint8_t)constrain(value.toInt(),1,255);else if(key=="TRAIL"||key=="FADE")effectTrail=(uint8_t)constrain(value.toInt(),1,255);
  else if(key=="DIR"){String v=value;v.toUpperCase();directionForward=!(v=="REV"||v=="REVERSE"||v=="-1"||v=="0");}else if(key=="MIRROR")mirrorMode=value.toInt()>0;
  else if(key=="ORDER")setOrder(value);else if(key=="AUDIO")audioEnabled=value.toInt()>0;else if(key=="AUDMODE")setAudioMode(value);else if(key=="AUDAMT")audioAmount=(uint8_t)constrain(value.toInt(),0,255);
  else if(key=="A"&&value.length()>=9){audioLevel=hexByteAt(value,0);audioBass=hexByteAt(value,2);audioMid=hexByteAt(value,4);audioHigh=hexByteAt(value,6);if(value[8]=='1')lastBeatAt=millis();audioRxCount++;synthesizeBinsFromFour();touchAudio();}
  else if((key=="F"||key=="FFT"||key=="FFT16")&&value.length()>=32){for(uint8_t i=0;i<16;i++)audioBins[i]=hexByteAt(value,(uint8_t)(i*2));summarizeBins();if(value.length()>32&&value[32]=='1')lastBeatAt=millis();lastSpectrumPacket=millis();spectrumRxCount++;touchAudio();}
  else if(key=="LEVEL"){audioLevel=(uint8_t)constrain(value.toInt(),0,255);touchAudio();}else if(key=="BASS"){audioBass=(uint8_t)constrain(value.toInt(),0,255);touchAudio();}
  else if(key=="MID"){audioMid=(uint8_t)constrain(value.toInt(),0,255);touchAudio();}else if(key=="HIGH"){audioHigh=(uint8_t)constrain(value.toInt(),0,255);touchAudio();}
  else if(key=="BEAT"){if(value.toInt()>0)lastBeatAt=millis();touchAudio();}
  else if(key=="LEDS"){long n=value.toInt();if(n<1)n=1;if(n>MAX_LEDS)n=MAX_LEDS;ledCount=(uint16_t)n;activeLedCount=ledCount;clearUnused();}
  else if(key=="PIN"){long p=value.toInt();if(p<0)p=0;if(p>39)p=39;dataPin=(uint8_t)p;}
  else if(key=="PSAVE"){savePreset((uint8_t)value.toInt());}
  else if(key=="PLOAD"){loadPreset((uint8_t)value.toInt());}
  else if(key=="PDEL"){deletePreset((uint8_t)value.toInt());}
  else if(key=="SAVE"||key=="STARTUP")saveSettings();
  else if(key=="LOAD"){loadSettings();FastLED.setBrightness(brightness);}
  else if(key=="STATUS")sendStatus();else if(key=="REBOOT"){saveSettings();delay(100);ESP.restart();}
}
void processCommand(String input){int start=0;while(start<input.length()){int end=input.indexOf(';',start);if(end<0)end=input.length();processSingleCommand(input.substring(start,end));start=end+1;}}

