class ServerCallbacks:public BLEServerCallbacks{
  void onConnect(BLEServer* server) override{bluetoothConnected=true;Serial.println("BLE connected");}
  void onDisconnect(BLEServer* server) override{bluetoothConnected=false;Serial.println("BLE disconnected");delay(100);BLEDevice::startAdvertising();}
};
class CommandCallbacks:public BLECharacteristicCallbacks{
  void onWrite(BLECharacteristic* characteristic) override{String command(characteristic->getValue().c_str());if(!command.length())return;Serial.print("BLE: ");Serial.println(command);processCommand(command);}
};
void setupBluetooth(){
  uint64_t chipID=ESP.getEfuseMac();char suffix[5];snprintf(suffix,sizeof(suffix),"%04X",(uint16_t)(chipID&0xFFFF));deviceName="ShyneTyme-MAIN-"+String(suffix);
  BLEDevice::init(deviceName.c_str());bleServer=BLEDevice::createServer();bleServer->setCallbacks(new ServerCallbacks());BLEService* service=bleServer->createService(SERVICE_UUID);
  commandCharacteristic=service->createCharacteristic(COMMAND_UUID,BLECharacteristic::PROPERTY_WRITE|BLECharacteristic::PROPERTY_WRITE_NR);commandCharacteristic->setCallbacks(new CommandCallbacks());
  statusCharacteristic=service->createCharacteristic(STATUS_UUID,BLECharacteristic::PROPERTY_READ|BLECharacteristic::PROPERTY_NOTIFY);statusCharacteristic->addDescriptor(new BLE2902());
  String status=buildStatus();statusCharacteristic->setValue(status.c_str());service->start();BLEAdvertising* advertising=BLEDevice::getAdvertising();advertising->addServiceUUID(SERVICE_UUID);advertising->setScanResponse(true);BLEDevice::startAdvertising();
  Serial.print("BLE name: ");Serial.println(deviceName);
}

