void effectComet(){
  uint8_t fade=(uint8_t)map(effectTrail,1,255,105,8);fadeTowardBackground(fade);uint8_t size=(uint8_t)map(reactiveSize(),1,255,1,18);
  for(uint8_t i=0;i<size;i++){uint16_t p=(motionPos+activeLedCount-i)%activeLedCount;putPixel(p,i==0?mainColor:mixColor(foregroundColor,mainColor,(uint8_t)map(i,0,size?size:1,180,20)));}
  motionPos=(motionPos+1)%activeLedCount;
