void effectMeteor(){
  uint8_t fade=(uint8_t)map(effectTrail,1,255,90,4);fadeTowardBackground(fade);uint8_t size=(uint8_t)map(reactiveSize(),1,255,2,24);
  for(uint8_t i=0;i<size;i++){uint16_t p=(motionPos+activeLedCount-i)%activeLedCount;CRGB c=mixColor(mainColor,foregroundColor,(uint8_t)map(i,0,size,0,220));c.nscale8_video((uint8_t)map(i,0,size,255,35));putPixel(p,c);}motionPos=(motionPos+1)%activeLedCount;
}
void effectScanner(){
  fill_solid(leds,activeLedCount,backgroundColor);uint8_t width=(uint8_t)map(reactiveSize(),1,255,1,28);if(width>activeLedCount)width=activeLedCount;
  for(uint8_t i=0;i<width;i++){int p=scannerPosition+i;if(p>=0&&p<(int)activeLedCount)putPixel((uint16_t)p,i==0?mainColor:foregroundColor);}scannerPosition+=scannerDirection;int end=(int)activeLedCount-(int)width;if(end<0)end=0;if(scannerPosition>=end)scannerDirection=-1;if(scannerPosition<=0)scannerDirection=1;
}
void effectDualScanner(){
  fill_solid(leds,activeLedCount,backgroundColor);uint8_t width=(uint8_t)map(reactiveSize(),1,255,1,18);uint16_t a=(uint16_t)scannerPosition,b=activeLedCount-1-a;
  for(uint8_t i=0;i<width;i++){if(a+i<activeLedCount)putPixel(a+i,i==0?mainColor:foregroundColor);if(b>=i)putPixel(b-i,i==0?mainColor:foregroundColor);}scannerPosition+=scannerDirection;int end=(int)activeLedCount/2-(int)width;if(end<1)end=1;if(scannerPosition>=end)scannerDirection=-1;if(scannerPosition<=0)scannerDirection=1;
