void effectPolice(){
  uint16_t period=(uint16_t)map(reactiveSpeed(),1,255,700,90),t=millis()%period;bool swap=t>period/2;uint16_t mid=activeLedCount/2;for(uint16_t i=0;i<activeLedCount;i++){bool left=i<mid;CRGB c=(left^swap)?foregroundColor:mainColor;putPixel(i,c);}
