void effectChase(){
  fill_solid(leds,activeLedCount,backgroundColor);uint8_t spacing=(uint8_t)map(reactiveDensity(),1,255,18,3);uint8_t width=(uint8_t)map(reactiveSize(),1,255,1,spacing>2?spacing-1:1);
