void effectTheater(){
  fill_solid(leds,activeLedCount,backgroundColor);uint8_t gap=(uint8_t)map(reactiveDensity(),1,255,8,3);for(uint16_t i=0;i<activeLedCount;i++)if(((i+chaseOffset)%gap)==0)putPixel(i,((i/gap)&1)?mainColor:foregroundColor);chaseOffset=(chaseOffset+1)%gap;
