void resetTwinkles(){for(auto &t:twinkles)t.active=false;}
void spawnTwinkle(uint8_t kind){
  for(auto &t:twinkles)if(!t.active){
    t.active=true;t.phase=0;t.role=random8()&1;t.pos=random16(activeLedCount);
    if(kind==2&&activeLedCount>8)t.pos=random16(activeLedCount-5);
    return;
  }
