void renderTwinkles(uint8_t kind){
  fill_solid(leds,activeLedCount,backgroundColor);
  uint8_t cap=(uint8_t)map(reactiveDensity(),1,255,2,42),active=0;
  for(auto &t:twinkles)if(t.active)active++;
  uint8_t chance=clamp8i((int)map(reactiveDensity(),1,255,18,210)+(int)map(reactiveSpeed(),1,255,0,38));
  if(active<cap&&random8()<chance)spawnTwinkle(kind);
  if(active+1<cap&&reactiveSpeed()>190&&random8()<105)spawnTwinkle(kind);
  if(active+2<cap&&reactiveSpeed()>235&&random8()<90)spawnTwinkle(kind);
  uint16_t step=(uint16_t)map(reactiveSpeed(),1,255,3,42);
  uint8_t halo=(uint8_t)map(effectTrail,1,255,18,145);
  uint8_t gap=(uint8_t)map(reactiveSize(),1,255,1,6);
  for(auto &t:twinkles){
    if(!t.active)continue;
    t.phase+=step;
    if(t.phase>=256){t.active=false;continue;}
    uint8_t pulse=triwave8((uint8_t)t.phase);
    CRGB c=scaled(t.role?mainColor:foregroundColor,pulse);
    putPixel(t.pos,c);
    if(kind==1){
      if(t.pos>0)addPixel(t.pos-1,scaled(c,halo));
      if(t.pos+1<activeLedCount)addPixel(t.pos+1,scaled(c,halo));
    }else if(kind==2){
      uint16_t p2=t.pos+gap;
      if(p2<activeLedCount)putPixel(p2,scaled(t.role?foregroundColor:mainColor,pulse));
      if(pulse>180&&t.pos>0)addPixel(t.pos-1,scaled(c,halo/2));
    }
  }
}
