void effectCatalog(){
  if(catalogEffect>=WLED_CATALOG_COUNT){effectOff();return;}const CatalogEntry &e=WLED_CATALOG[catalogEffect];
  switch(e.family){
    case CF_BLINK:renderCatalogBlink(e.variant);break;case CF_CHASE:renderCatalogChase(e.variant);break;case CF_SCAN:renderCatalogScan(e.variant);break;
    case CF_NOISE:renderCatalogNoise(e.variant);break;case CF_TWINKLE:renderCatalogTwinkle(e.variant);break;case CF_FIRE:renderCatalogFire(e.variant);break;
    case CF_PARTICLE:renderCatalogParticle(e.variant);break;case CF_AUDIO:renderCatalogAudio(e.variant);break;case CF_WIPE:renderCatalogWipe(e.variant);break;
    case CF_WAVE:renderCatalogWave(e.variant);break;case CF_PATTERN:renderCatalogPattern(e.variant);break;case CF_PS:renderCatalogPS(e.variant);break;
  }
}

// Audio modulation stays layered on every selected effect instead of replacing it.
// V5.2 avoids introducing palette/gradient colors: modulation scales current pixels
// and accents with the three user roles only.
void applyAudioOverlay(){
  if(!audioLive())return;
  bool level=(audioMode==AM_LEVEL||audioMode==AM_FULL);
  bool spectrum=(audioMode==AM_SPECTRUM||audioMode==AM_FULL);
  bool beat=(audioMode==AM_BEAT||audioMode==AM_FULL);
  if(level&&currentEffect!=FX_VU&&currentEffect!=FX_AUDIO_PULSE){
    uint8_t gain=(uint8_t)map((uint16_t)audioLevel*audioAmount>>8,0,255,150,255);
    for(uint16_t i=0;i<activeLedCount;i++)leds[i].nscale8_video(gain);
  }
  if(spectrum&&currentEffect!=FX_SPECTRUM){
    uint16_t n=max((uint16_t)1,activeLedCount);for(uint8_t b=0;b<16;b++){uint8_t a=audioBin(b);if(a<150)continue;uint16_t p=(uint16_t)(((uint32_t)b*(n-1))/15);uint8_t role=(b<5)?1:2;putPixel(p,catalogRoleScaled(role,a));}
  }
  if(beat&&beatLive()&&currentEffect!=FX_BEAT_FLASH&&currentEffect!=FX_SONIC_BOOM&&currentEffect!=FX_STARBURST){
    uint8_t spacing=(uint8_t)map(audioAmount,0,255,14,4);for(uint16_t i=0;i<activeLedCount;i+=spacing)putPixel(i,mainColor);
  }
}

void runEffect(){
  switch(currentEffect){
    case FX_OFF:effectOff();break;case FX_SOLID:effectSolid();break;case FX_RAINBOW:effectRainbow();break;case FX_RAINBOW_GLITTER:effectRainbowGlitter();break;
    case FX_COMET:effectComet();break;case FX_METEOR:effectMeteor();break;case FX_SCANNER:effectScanner();break;case FX_DUAL_SCANNER:effectDualScanner();break;case FX_POLICE:effectPolice();break;
    case FX_CHASE:effectChase();break;case FX_TRICOLOR_CHASE:effectTricolorChase();break;case FX_RUNNING_DOTS:effectRunningDots();break;case FX_THEATER:effectTheater();break;case FX_WIPE:effectWipe();break;
    case FX_FLOW:effectFlow();break;case FX_FLOW_STRIPE:effectFlowStripe();break;case FX_COLOR_WAVES:effectColorWaves();break;
    case FX_SPARKLE:effectSparkle();break;case FX_GLITTER:effectGlitter();break;case FX_TWINKLE:effectTwinkle();break;case FX_TWINKLEFOX:effectTwinkleFox();break;case FX_TWINKLECAT:effectTwinkleCat();break;
    case FX_FIREWORKS:effectFireworks();break;case FX_RAIN:effectRain();break;case FX_TETRIX:effectTetrix();break;case FX_FIRE:effectFire();break;case FX_LIGHTNING:effectLightning();break;
    case FX_PACIFICA:effectPacifica();break;case FX_SUNRISE:effectSunrise();break;case FX_DANCING_SHADOWS:effectDancingShadows();break;case FX_PRIDE:effectPride();break;
    case FX_SINELON:effectSinelon();break;case FX_JUGGLE:effectJuggle();break;case FX_RIPPLE:effectRipple();break;case FX_SONIC_STREAM:effectSonicStream();break;case FX_SONIC_BOOM:effectSonicBoom();break;
    case FX_STARBURST:effectStarburst();break;case FX_BOUNCING_BALLS:effectBouncingBalls();break;case FX_POPCORN:effectPopcorn();break;case FX_DRIPDROP:effectDripDrop();break;
    case FX_LAVA_LAMP:effectLavaLamp();break;case FX_MAGMA:effectMagma();break;case FX_AURORA:effectAurora();break;case FX_HEARTBEAT:effectHeartbeat();break;
    case FX_BREATHE:effectBreathe();break;case FX_FLASH:effectFlash();break;case FX_DUAL_FLASH:effectDualFlash();break;
    case FX_VU:effectVU();break;case FX_SPECTRUM:effectSpectrum();break;case FX_AUDIO_PULSE:effectAudioPulse();break;case FX_BEAT_FLASH:effectBeatFlash();break;
    case FX_WLED_CATALOG:effectCatalog();break;
  }
  applyAudioOverlay();showFrame();
}

// ---------- SETUP / LOOP ----------
void setup(){
  Serial.begin(115200);delay(350);Serial.println();Serial.println("======================");Serial.println("SHYNETYME BT V5.2 MAIN");Serial.println("======================");
  loadSettings();bool pinOK=configureLEDOutput(activeDataPin);if(!pinOK)Serial.println("Unsupported GPIO saved. Using GPIO 13.");FastLED.setBrightness(brightness);FastLED.setMaxPowerInVoltsAndMilliamps(5,2500);
  fill_solid(leds,MAX_LEDS,CRGB::Black);fill_solid(outputLeds,MAX_LEDS,CRGB::Black);showFrame();setupBluetooth();
  Serial.print("LEDs: ");Serial.println(activeLedCount);Serial.print("GPIO: ");Serial.println(activeDataPin);Serial.print("Order: ");Serial.println(orderName());Serial.println("Waiting for Bluetooth controller...");
}
void loop(){
  uint16_t frameInterval=(uint16_t)map(reactiveSpeed(),1,255,55,5);if(millis()-lastFrame>=frameInterval){lastFrame=millis();runEffect();}
}
